// Muster mit Namen statt Zahlen
const PATTERNS = [
  [/^Verzögerung (.+) in ms$/, (m) => `Delay ${m[1]} in ms`],
  [/^Verzögerung (.+)$/, (m) => `Delay ${m[1]}`],
  [/^Verbunden mit (.+)$/, (m) => `Connected to ${m[1]}`],
  [/^Verbinde mit (.+) …$/, (m) => `Connecting to ${m[1]} …`],
  [/^Rechner für (.+)$/, (m) => `Computer for ${m[1]}`],
  [/^(.+) \(nicht verbunden\)$/, (m) => `${m[1]} (not connected)`],
  [/^Uhr ±(.+) ms$/, (m) => `Clock ±${m[1]} ms`],
  [/^(\d+) Dateien bereit$/, (m) => `${m[1]} files ready`],
  [/^Dateien (\d+) von (\d+)$/, (m) => `Files ${m[1]} of ${m[2]}`],
  [/^zeigt (.+)$/, (m) => `shows ${m[1]}`],
  [/^(\d+) bereit$/, (m) => `${m[1]} ready`],
  [/^(.+) von (.+ MB)$/, (m) => `${m[1]} of ${m[2]}`],
  [/^(\d+) alte Dateien gelöscht$/, (m) => `${m[1]} old files deleted`],
  [/^Verbund: (.+)$/, (m) => `Cluster: ${m[1]}`],
  [/^(.+) wird gerade nicht ausgegeben\. Ausgänge öffnen und Zuordnung unter „Einrichten“ prüfen\.$/, (m) => `${tr(m[1])} is not being output right now. Open the outputs and check the assignment under “Set up”.`],
  [/^Kamera: (.+)$/, (m) => `Camera: ${m[1]}`],
  [/^(.+): Muster (\d+) von (\d+)$/, (m) => `${tr(m[1])}: pattern ${m[2]} of ${m[3]}`],
  [/^Die Kamera sieht kein Licht von (.+)\. Kamera auf die Fläche dieses Projektors richten\.$/, (m) => `The camera sees no light from ${tr(m[1])}. Point the camera at this projector's area.`],
  [/^Kamera-Standort: (.+) Kamera so drehen, dass sie mehr von (.+) sieht\.$/, (m) => `Camera position: ${tr(m[1])} Turn the camera so that it sees more of ${tr(m[2])}.`],
  [/^Die Kamera sieht zu wenig von (.+)\. Kamera mehr auf diesen Projektor richten\.$/, (m) => `The camera sees too little of ${tr(m[1])}. Point the camera more at this projector.`],
  [/^(.+): (\d+) Kamera-Punkte übernommen$/, (m) => `${tr(m[1])}: ${m[2]} camera points applied`],
  [/^(.+) mit Kamera kalibrieren$/, (m) => `Calibrate ${tr(m[1])} with camera`],
  [/^Die Kamera hat neu scharfgestellt, das hat nicht geholfen\. Wahrscheinlich ist (.+) unscharf: Fokusring am Projektor drehen, bis der Balken ganz voll ist\.$/, (m) => `The camera refocused, but that did not help. ${tr(m[1])} is probably out of focus: turn the focus ring on the projector until the bar is completely full.`],
  [/^(.+) oder die Kamera ist unscharf\. Erst den Fokusring am Projektor drehen, bis der Balken voll ist\. Hilft das nicht, „Kamera scharfstellen“\.$/, (m) => `${tr(m[1])} or the camera is out of focus. First turn the focus ring on the projector until the bar is full. If that does not help, use “Focus camera”.`],
  [/^(.+) oder die Kamera ist unscharf\. Fokusring am Projektor drehen, bis der Balken voll ist\. Hilft das nicht, die Kamera näher heran oder an ihrem Objektiv scharfstellen\.$/, (m) => `${tr(m[1])} or the camera is out of focus. Turn the focus ring on the projector until the bar is full. If that does not help, move the camera closer or focus its lens.`],
  [/^Bildmitte für (.+) gesetzt$/, (m) => `Image center set for ${tr(m[1])}`],
  [/^(.+) und (.+) haben die Bildschirme getauscht\.$/, (m) => `${m[1]} and ${m[2]} swapped displays.`],
  [/^Bildschirm für (.+)$/, (m) => `Display for ${m[1]}`],
  [/^(.+): nur (\d+) Felder für (\d+) Projektoren\. Überzählige teilen sich ein Feld\.$/, (m) => `${tr(m[1])}: only ${m[2]} cells for ${m[3]} projectors. Extra ones share a cell.`],
  [/^(.+): Projektoren auf (.+) verteilt\.$/, (m) => `${m[1]}: projectors arranged as ${tr(m[2])}.`],
  [/^Ungefähr dorthin klicken, wo die Mitte des Bildes von (.+) liegt\.$/, (m) => `Click roughly where the center of the image of ${tr(m[1])} is.`],
  [/^Am besten weit außen im Bild von (.+) beginnen\.$/, (m) => `Best start far out in the image of ${tr(m[1])}.`],
  [/^Mit (.+) beginnen$/, (m) => `Start with ${tr(m[1])}`],
  [/^Zuletzt (.+) um (.+)$/, (m) => `Last: ${tr(m[1])} at ${m[2]}`],
  [/^Fehler: (.+)$/, (m) => `Error: ${m[1]}`],
  [/^Modell konnte nicht geladen werden: (.+)$/, (m) => `Model could not be loaded: ${m[1]}`],
  [/^Export fertig: (\d+) Projektor\(en\) → (.+)$/, (m) => `Export finished: ${m[1]} projector(s) → ${m[2]}`],
  [/^Punkt (\S+) passt schlecht \((.+) px\) – evtl\. falsch zugeordnet\?$/, (m) => `Point ${m[1]} fits poorly (${m[2]} px) – possibly mismatched?`],
  [/^Bildrate je Ausgang: (.+)$/, (m) => `Frame rate per output: ${tr(m[1])}`],
  [/^(.+) · (\d+) Kanäle · (.+) kHz · (\d+) ms$/, (m) => `${tr(m[1])} · ${m[2]} channels · ${m[3]} kHz · ${m[4]} ms`],
  [/^(.+) hinzugefügt, (.+)$/, (m) => `${tr(m[1])} added, ${tr(m[2])}`],
  [/^(.+) hinzugefügt\. Alle Felder sind belegt, bitte einen Ausgang wählen\.$/, (m) => `${tr(m[1])} added. All cells are taken, please choose an output.`],
  [/^(\d+ × \d+) \(nativ\)$/, (m) => `${m[1]} (native)`],
  [/^Projektoren ([\d, ]+)$/, (m) => `Projectors ${m[1]}`],
  [/^Mikrofon: (.+)$/, (m) => `Microphone: ${m[1]}`],
  [/^(An|Aus) · (\d+) Messstellen · (.+)$/, (m) => `${m[1] === 'An' ? 'On' : 'Off'} · ${m[2]} spots · ${m[3]}`],
  [/^Handy: (.+)$/, (m) => `Phone: ${m[1]}`],
  [/^\+(.+) ms$/, (m) => `+${m[1]} ms`],
  [/^Ausgang (.+)$/, (m) => `Output ${m[1]}`],
  [/^Bild von (.+)$/, (m) => `Image of ${tr(m[1])}`],
  [/^Punkt (\S*) passt nicht \((.+) px\)$/, (m) => `Point ${m[1]} does not fit (${m[2]} px)`],
  [/^Punkt (\d+)$/, (m) => `Point ${m[1]}`],
  [/^Gruppe (\d+)$/, (m) => `Group ${m[1]}`],
  [/^(.+) tauscht den Platz$/, (m) => `${tr(m[1])} swaps places`],
  [/^(.+): frei$/, (m) => `${tr(m[1])}: free`],
  [/^(.+) → (.+)$/, (m) => `${tr(m[1])} → ${tr(m[2])}`],
];

const NUM = /\d+(?:[.,]\d+)?/g;

/** Text in der eingestellten Sprache. */
export function tr(s) {
  if (lang === 'de' || typeof s !== 'string' || !s) return s;
  const hit = EN[s];
  if (hit !== undefined) return hit;
  if (s.includes(' · ')) return s.split(' · ').map(tr).join(' · ');
  const nums = [];
  const key = s.replace(NUM, (n) => `{${nums.push(n) - 1}}`);
  if (nums.length && EN[key] !== undefined) return EN[key].replace(/\{(\d+)\}/g, (_, i) => nums[i]);
  for (const [re, fn] of PATTERNS) { const m = s.match(re); if (m) return fn(m); }
  return s;
}

/**
 * Statisches HTML übersetzen (Texte und Attribute). Der erste Aufruf merkt sich die Knoten mit ihrem
 * deutschen Original; spätere Aufrufe übersetzen nur diese. Dynamisch erzeugte Teile baut die App neu.
 */
const registry = new WeakMap();
export function translateDom(root) {
  let reg = registry.get(root);
  if (!reg) {
    reg = { texts: [], attrs: [] };
    const walker = root.ownerDocument.createTreeWalker(root, 4 /* NodeFilter.SHOW_TEXT */);
    for (let n = walker.nextNode(); n; n = walker.nextNode()) if (n.nodeValue.trim()) reg.texts.push([n, n.nodeValue]);
    for (const e of root.querySelectorAll('[data-tip],[aria-label],[title],[placeholder]'))
      for (const a of ['data-tip', 'aria-label', 'title', 'placeholder']) if (e.hasAttribute(a)) reg.attrs.push([e, a, e.getAttribute(a)]);
    registry.set(root, reg);
  }
  for (const [n, orig] of reg.texts) {
    if (!n.isConnected) continue;
    const lead = orig.match(/^\s*/)[0], trail = orig.match(/\s*$/)[0];
    n.nodeValue = lead + tr(orig.trim()) + trail;
  }
  for (const [e, a, orig] of reg.attrs) if (e.isConnected) e.setAttribute(a, tr(orig));
}
